from tri import build
A = ['uk', 'pl', 'en']
build(1, dict(
 title='Перший день|Pierwszy dzień|First Day',
 scene='Каліфорнійське бюро розслідувань, Сакраменто. Ти — новий аналітик-стажист у команді агентки Терези Лісабон. Тобі видають порожній стіл, стос справ і одне попередження: «Не звертай уваги на чоловіка на дивані». На дивані з чашкою чаю лежить Патрік Джейн — колишній «медіум», який тепер допомагає поліції. За три хвилини він знає про тебе більше, ніж твоя мама.|Kalifornijskie Biuro Śledcze, Sacramento. Jesteś nowym analitykiem-stażystą w zespole agentki Teresy Lisbon. Dostajesz puste biurko, stos akt i jedno ostrzeżenie: „Nie zwracaj uwagi na faceta na kanapie”. Na kanapie, z filiżanką herbaty, leży Patrick Jane — były „medium”, który teraz pomaga policji. Po trzech minutach wie o tobie więcej niż twoja mama.|The California Bureau of Investigation, Sacramento. You are the new trainee analyst on Agent Teresa Lisbon\'s team. You get an empty desk, a pile of case files and one warning: “Ignore the man on the couch.” On the couch, with a cup of tea, lies Patrick Jane, a former “psychic” who now helps the police. Within three minutes he knows more about you than your mother does.',
 prev='Каліфорнія. Бюро розслідувань (CBI) займається найскладнішими вбивствами штату. Команда агентки Лісабон має найкращий результат у бюро — і найдивнішого консультанта.|Kalifornia. Biuro śledcze (CBI) zajmuje się najtrudniejszymi zabójstwami w stanie. Zespół agentki Lisbon ma najlepsze wyniki w biurze — i najdziwniejszego konsultanta.|California. The Bureau of Investigation (CBI) handles the hardest murder cases in the state. Agent Lisbon\'s team has the best record in the bureau, and the strangest consultant.',
 cards=[('Патрік Джейн', 'Patrick Jane', 'Колись удавав медіума на телебаченні. Тепер читає людей, як відкриту книгу, — і ніколи не пояснює як.|Kiedyś udawał medium w telewizji. Teraz czyta ludzi jak otwartą książkę — i nigdy nie wyjaśnia jak.|He used to pretend to be a TV psychic. Now he reads people like an open book, and never explains how.'),
        ('Тереза Лісабон', 'Teresa Lisbon', 'Старша агентка й твоя начальниця. Любить правила. Не любить, коли Джейн їх порушує.|Starsza agentka i twoja szefowa. Kocha zasady. Nie znosi, kiedy Jane je łamie.|Senior agent and your boss. She loves rules. She hates it when Jane breaks them.'),
        ('Кімбол Чо', 'Kimball Cho', 'Говорить мало. Помічає все.|Mówi mało. Zauważa wszystko.|He says little. He notices everything.'),
        ('Вейн Ріґсбі', 'Wayne Rigsby', 'Високий, добрий і завжди голодний. Чомусь нервує поруч із Ґрейс.|Wysoki, życzliwy i zawsze głodny. Z jakiegoś powodu denerwuje się przy Grace.|Tall, kind and always hungry. For some reason he gets nervous around Grace.'),
        ('Ґрейс Ван Пелт', 'Grace Van Pelt', 'Теж новенька. Вірить у те, у що Джейн давно не вірить.|Też nowa. Wierzy w to, w co Jane dawno przestał wierzyć.|New here too. She believes in things Jane stopped believing in long ago.')],
 gname={'en': 'Present simple, present continuous and present perfect; stative verbs (know, seem, belong, mean)|Present simple, continuous, perfect; czasowniki stanu|Present tenses and stative verbs',
        'pl': 'Czas teraźniejszy: nawyk, czynność teraz i stan; już / jeszcze nie / od + teraźniejszy|Czas teraźniejszy, już / od|Polish present: habit, now, state; już / od',
        'uk': 'Теперішній час: звичка, дія зараз і стан; вже / ще не / з + теперішній|Теперішній час, вже / з|Ukrainian present: habit, now, state; вже / з'},
 where='Відділ серйозних злочинів CBI, понеділок, 8:15 ранку.|Wydział poważnych przestępstw CBI, poniedziałek, 8:15 rano.|The CBI Serious Crimes Unit, Monday, 8:15 a.m.',
 role='Ти тримаєш картонну коробку з речами й шукаєш свій стіл. Агентка Лісабон уже кричить у телефон, хтось смажить попкорн у мікрохвильовці, а чоловік на дивані відкриває одне око й усміхається тобі так, ніби вже все про тебе знає. Що він помітив?|Trzymasz kartonowe pudło z rzeczami i szukasz swojego biurka. Agentka Lisbon już krzyczy do telefonu, ktoś robi popcorn w mikrofalówce, a mężczyzna na kanapie otwiera jedno oko i uśmiecha się do ciebie tak, jakby już wszystko o tobie wiedział. Co zauważył?|You are holding a cardboard box of your things and looking for your desk. Agent Lisbon is already shouting into the phone, someone is making popcorn in the microwave, and the man on the couch opens one eye and smiles at you as if he already knows everything about you. What has he noticed?',
 sc=[('Новий стіл|Nowe biurko|A New Desk', 'стажист|stażysta|trainee;стіл|biurko|desk;справа|akta|case file;попередження|ostrzeżenie|warning;звертати увагу|zwracać uwagę|to pay attention', [
   'Ти тут [стажист], і всі це бачать.|Jesteś tu [stażystą] i wszyscy to widzą.|You are a [trainee] here, and everyone can see it.',
   'Твій [стіл] стоїть біля самого дивана.|Twoje [biurko] stoi tuż obok kanapy.|Your [desk] stands right next to the couch.',
   'На ньому вже лежить товста [справа].|Leżą już na nim grube [akta].|A thick [case file] is already lying on it.',
   'Ріґсбі дає тобі одне [попередження].|Rigsby daje ci jedno [ostrzeżenie].|Rigsby gives you one [warning].',
   '«Не [звертай] уваги на Джейна», — каже він.|„Nie [zwracaj] uwagi na Jane\'a” — mówi.|“Don\'t [pay] attention to Jane,” he says.',
   'Джейн [працює/працюватиме/працюючи] в CBI вже п\'ять років.|Jane [pracuje/będzie pracował/pracując] w CBI od pięciu lat.|Jane [has worked/works/is working] at the CBI for five years.']),
  ('Чоловік на дивані|Facet na kanapie|The Man on the Couch', 'диван|kanapa|couch;чай|herbata|tea;консультант|konsultant|consultant;усміхатися|uśmiechać się|to smile;вгадувати|zgadywać|to guess', [
   'Джейн лежить на старому шкіряному [дивані].|Jane leży na starej skórzanej [kanapie].|Jane lies on the old leather [couch].',
   'Він п\'є [чай] з блакитної чашки.|Pije [herbatę] z niebieskiej filiżanki.|He drinks [tea] from a blue cup.',
   'Офіційно він — [консультант] CBI.|Oficjalnie jest [konsultantem] CBI.|Officially he is a CBI [consultant].',
   'Він знову [усміхається] тобі.|Znowu się do ciebie [uśmiecha].|He [smiles] at you again.',
   'Він не [вгадує] — він бачить.|On nie [zgaduje] — on widzi.|He doesn\'t [guess] — he sees.',
   'Чому ти [дивишся/подивишся/дивлячись] на мене так?|Dlaczego tak na mnie [patrzysz/popatrzysz/patrząc]?|Why [are you looking/do you look/you look] at me like that?']),
  ('Перше читання|Pierwsze czytanie|The First Reading', 'нігті|paznokcie|nails;годинник|zegarek|watch;брехати|kłamać|to lie;звичка|nawyk|habit;деталь|szczegół|detail', [
   'Джейн дивиться на твої [нігті] і сміється.|Jane patrzy na twoje [paznokcie] i się śmieje.|Jane looks at your [nails] and laughs.',
   'Твій [годинник] показує чужий час.|Twój [zegarek] pokazuje cudzy czas.|Your [watch] shows a different time zone.',
   'Ти намагаєшся [брехати], але червонієш.|Próbujesz [kłamać], ale się czerwienisz.|You try to [lie], but you blush.',
   'Гризти нігті — твоя давня [звичка].|Obgryzanie paznokci to twój stary [nawyk].|Biting your nails is an old [habit] of yours.',
   'Для нього важлива кожна [деталь].|Dla niego liczy się każdy [szczegół].|Every [detail] matters to him.',
   'Я вже [знаю/знатиму/знаючи], що ти не спав уночі.|Już [wiem/będę wiedział/wiedząc], że nie spałeś w nocy.|I already [know/am knowing/knowing] you didn\'t sleep last night.'])],
 rule={'uk': 'В українській один теперішній час, але три значення. Звичка: «Джейн щоранку п\'є чай». Дія зараз: «Чому ти зараз дивишся на мене?». Стан, що триває досі, — теперішній + з / вже: «Джейн працює в CBI вже п\'ять років» (не минулий!). Дієслова стану — знати, вірити, належати — не мають «процесу»: «Я знаю», а не «я знаю зараз у процесі».',
       'pl': 'W polskim jeden czas teraźniejszy, ale trzy znaczenia. Nawyk: „Jane co rano pije herbatę”. Czynność teraz: „Dlaczego teraz na mnie patrzysz?”. Stan trwający do dziś — teraźniejszy + od / już: „Jane pracuje w CBI od pięciu lat” (nie przeszły!). Czasowniki stanu — wiedzieć, wierzyć, należeć — nie opisują procesu: „Wiem”, a nie „jestem w trakcie wiedzenia”.',
       'en': 'Present simple: habits and facts (Jane drinks tea every morning). Present continuous: actions happening now or temporary situations (Why are you looking at me?). Present perfect: a state or habit from the past up to now, with for / since (Jane has worked at the CBI for five years). Stative verbs — know, believe, seem, belong, mean — are not normally used in continuous forms: I know, not I am knowing.'},
 gram=['Лісабон [ненавидить/ненавидітиме/ненавидячи], коли Джейн порушує правила.|Lisbon [nienawidzi/będzie nienawidzić/nienawidząc], kiedy Jane łamie zasady.|Lisbon [hates/is hating/has hated] it when Jane breaks the rules.',
  'Тихо! Чо зараз [говорить/говоритиме/говорячи] з підозрюваним.|Cicho! Cho [rozmawia/będzie rozmawiał/rozmawiając] teraz z podejrzanym.|Quiet! Cho [is talking/talks/has talked] to a suspect right now.',
  'Ріґсбі [знає/знатиме/знаючи] Ґрейс лише тиждень.|Rigsby [zna/będzie znał/znając] Grace dopiero od tygodnia.|Rigsby [has known/is knowing/knows] Grace for only a week.',
  'Джейн ніколи не [пояснює/пояснювати/пояснюючи] своїх трюків.|Jane nigdy nie [wyjaśnia/wyjaśniać/wyjaśniając] swoich sztuczek.|Jane never [explains/is explaining/has explained] his tricks.',
  'Цей диван [належить/належати/належачи] Джейнові — ніхто інший на ньому не сидить.|Ta kanapa [należy/należeć/należąc] do Jane\'a — nikt inny na niej nie siada.|This couch [belongs/is belonging/has belonging] to Jane — nobody else sits on it.',
  'Цього тижня Ґрейс [вивчає/вивчати/вивчаючи] старі справи.|W tym tygodniu Grace [przegląda/przeglądać/przeglądając] stare akta.|This week Grace [is studying/studies/has studied] old case files.',
  'Ти [здаєшся/здаватися/здаючись] утомленим — ти не спав?|[Wydajesz się/Wydawać się/Wydając się] zmęczony — nie spałeś?|You [seem/are seeming/have seemed] tired — didn\'t you sleep?',
  'Я ще не [бачив/бачу/бачачи] такого дивного консультанта.|Jeszcze nie [widziałem/widzę/widząc] tak dziwnego konsultanta.|I [have never seen/never see/am never seeing] such a strange consultant.',
  'Що ти [робиш/робити/роблячи] з моєю чашкою, Ріґсбі?|Co [robisz/robić/robiąc] z moją filiżanką, Rigsby?|What [are you doing/do you do/have you done] with my cup, Rigsby?',
  'Лісабон [керує/керувати/керуючи] командою вже три роки.|Lisbon [kieruje/kierować/kierując] zespołem od trzech lat.|Lisbon [has run/runs/is running] the team for three years.',
  'Я не [вірю/вірити/вірячи] у медіумів, — каже Джейн.|Nie [wierzę/wierzyć/wierząc] w media — mówi Jane.|“I [don\'t believe/am not believing/haven\'t believed] in psychics,” says Jane.',
  'Що [означає/означати/означаючи] цей знак на справі?|Co [oznacza/oznaczać/oznaczając] ten znak na aktach?|What [does this mark mean/is this mark meaning/has this mark meant] on the file?'],
 rt='Пам\'ятка для нових співробітників відділу (неофіційна, написана Ріґсбі)|Ściągawka dla nowych pracowników wydziału (nieoficjalna, napisana przez Rigsby\'ego)|A guide for new staff in the unit (unofficial, written by Rigsby)',
 read=['Ласкаво просимо до відділу серйозних злочинів — найкращої [команди] в CBI.|Witaj w wydziale poważnych przestępstw — najlepszym [zespole] w CBI.|Welcome to the Serious Crimes Unit, the best [team] in the CBI.',
  'Агентка Лісабон керує нами вже три [роки].|Agentka Lisbon kieruje nami od trzech [lat].|Agent Lisbon has run the team for three [years].',
  'Вона приходить о сьомій і йде [останньою].|Przychodzi o siódmej i wychodzi [ostatnia].|She arrives at seven and leaves [last].',
  'Звіти треба здавати до п\'ятої — вона не [приймає] запізнень.|Raporty trzeba oddawać do piątej — ona nie [przyjmuje] spóźnień.|Reports are due by five: she doesn\'t [accept] late ones.',
  'Чо говорить мало, але завжди [помічає] брехню.|Cho mówi mało, ale zawsze [zauważa] kłamstwo.|Cho says little, but he always [notices] a lie.',
  'Ван Пелт працює з нами лише [тиждень].|Van Pelt pracuje z nami dopiero od [tygodnia].|Van Pelt has worked with us for only a [week].',
  'Вона [вірить] у медіумів, тож не сперечайся з нею при Джейні.|Ona [wierzy] w media, więc nie kłóć się z nią przy Janie.|She [believes] in psychics, so don\'t argue with her in front of Jane.',
  'Тепер про Джейна: він не агент, а [консультант].|Teraz o Janie: on nie jest agentem, tylko [konsultantem].|Now about Jane: he isn\'t an agent, he\'s a [consultant].',
  'Він лежить на дивані, п\'є чай і, здається, [спить].|Leży na kanapie, pije herbatę i chyba [śpi].|He lies on the couch, drinks tea and seems to be [asleep].',
  'Насправді він слухає [кожне] слово.|Naprawdę słucha [każdego] słowa.|In fact he is listening to [every] word.',
  'Він помічає те, чого не бачать інші: нігті, взуття, [годинник].|Zauważa to, czego nie widzą inni: paznokcie, buty, [zegarek].|He notices what others miss: nails, shoes, a [watch].',
  'Якщо він каже щось про твоє життя, не [червоній].|Jeśli mówi coś o twoim życiu, nie [czerwień] się.|If he says something about your life, don\'t [blush].',
  'Він робить це з усіма — навіть із [Лісабон].|Robi to wszystkim — nawet [Lisbon].|He does it to everyone, even [Lisbon].',
  'І найголовніше: ніколи не питай його про [Червоного] Джона.|I najważniejsze: nigdy nie pytaj go o [Red] Johna.|And most important: never ask him about [Red] John.',
  'Коли він почує це ім\'я, він перестає [усміхатися].|Kiedy słyszy to imię, przestaje się [uśmiechać].|When he hears that name, he stops [smiling].',
  'P.S. Мій попкорн у холодильнику — не [чіпай].|P.S. Mój popcorn w lodówce — nie [ruszaj].|P.S. My popcorn is in the fridge. Don\'t [touch] it.'],
 chk=[('Хто написав пам\'ятку?|Kto napisał ściągawkę?|Who wrote the guide?', ['Ріґсбі|Rigsby|Rigsby', 'Лісабон|Lisbon|Lisbon', 'Джейн|Jane|Jane']),
  ('Чого не приймає Лісабон?|Czego nie przyjmuje Lisbon?|What does Lisbon not accept?', ['Запізнених звітів|Spóźnionych raportów|Late reports', 'Чаю на роботі|Herbaty w pracy|Tea at work', 'Нових стажистів|Nowych stażystów|New trainees']),
  ('Чому не варто сперечатися з Ван Пелт при Джейні?|Dlaczego nie warto kłócić się z Van Pelt przy Janie?|Why shouldn\'t you argue with Van Pelt in front of Jane?', ['Бо вона вірить у медіумів|Bo ona wierzy w media|Because she believes in psychics', 'Бо вона начальниця|Bo jest szefową|Because she is the boss', 'Бо Джейн спить|Bo Jane śpi|Because Jane is asleep']),
  ('Що насправді робить Джейн на дивані?|Co naprawdę robi Jane na kanapie?|What is Jane really doing on the couch?', ['Слухає кожне слово|Słucha każdego słowa|Listening to every word', 'Спить|Śpi|Sleeping', 'Пише звіти|Pisze raporty|Writing reports']),
  ('Про що ніколи не можна питати Джейна?|O co nigdy nie wolno pytać Jane\'a?|What must you never ask Jane about?', ['Про Червоного Джона|O Red Johna|Red John', 'Про чай|O herbatę|Tea', 'Про Лісабон|O Lisbon|Lisbon'])],
 qq='Джейн сідає на дивані й плескає по місцю поруч: «Гра. Я кажу про тебе три речі, ти кажеш — правда чи ні. А потім ти кажеш три речі про мене». Відповідай теперішнім часом — точно, як у звіті.|Jane siada na kanapie i klepie miejsce obok: „Gra. Mówię o tobie trzy rzeczy, ty mówisz — prawda czy nie. A potem ty mówisz trzy rzeczy o mnie”. Odpowiadaj czasem teraźniejszym — dokładnie, jak w raporcie.|Jane sits up on the couch and pats the seat beside him: “A game. I say three things about you, you say true or false. Then you tell me three things about me.” Answer in the present, as precisely as in a report.',
 quest=[('Джейн: Ти не спав сьогодні вночі. Чому?|Jane: Nie spałeś dziś w nocy. Dlaczego?|Jane: You didn\'t sleep last night. Why?', 'Я завжди погано сплю перед першим днем.|Zawsze źle śpię przed pierwszym dniem.|I always sleep badly before a first day.', 'Я завжди погано сплячи перед першим днем.|Zawsze źle śpiąc przed pierwszym dniem.|I am always sleeping badly before a first day.'),
  ('Джейн: А чому твій годинник показує інший час?|Jane: A dlaczego twój zegarek pokazuje inny czas?|Jane: And why does your watch show a different time?', 'Моя сестра живе в Нью-Йорку, і я так знаю її час.|Moja siostra mieszka w Nowym Jorku i tak znam jej czas.|My sister lives in New York, so I always know her time.', 'Моя сестра живучи в Нью-Йорку.|Moja siostra mieszkając w Nowym Jorku.|My sister is living in New York since years.'),
  ('Джейн: Добре. Тепер ти. Що ти бачиш у мені?|Jane: Dobrze. Teraz ty. Co widzisz we mnie?|Jane: Good. Now you. What do you see in me?', 'Ви п\'єте чай із тієї самої чашки щодня.|Codziennie pije pan herbatę z tej samej filiżanki.|You drink tea from the same cup every day.', 'Ви п\'ючи чай із тієї самої чашки.|Pije pan pijąc herbatę z tej samej filiżanki.|You are drinking tea from the same cup every day.'),
  ('Джейн: Вражає. І ще одне?|Jane: Imponujące. I jeszcze jedno?|Jane: Impressive. One more?', 'Ви працюєте тут давно, але досі не маєте свого столу.|Pracuje pan tu od dawna, ale wciąż nie ma pan biurka.|You have worked here for years, but you still don\'t have a desk.', 'Ви працювали тут давно, але досі не мавши столу.|Pracował pan tu od dawna, ale wciąż nie mając biurka.|You are working here for years, but you still don\'t have a desk.')],
 qend='Джейн сміється — щиро, уперше за ранок. «Стіл мені не потрібен. У мене є диван». Він кладе на твою справу маленький сірий конверт. На ньому від руки написано дві літери: «Ч. Д.». «Не відкривай при Лісабон», — шепоче він. А Лісабон уже стоїть позаду тебе.|Jane się śmieje — szczerze, pierwszy raz tego ranka. „Biurko nie jest mi potrzebne. Mam kanapę”. Kładzie na twoich aktach małą szarą kopertę. Odręcznie napisano na niej dwie litery: „R. J.”. „Nie otwieraj przy Lisbon” — szepcze. A Lisbon już stoi za tobą.|Jane laughs, genuinely, for the first time that morning. “I don\'t need a desk. I have a couch.” He puts a small grey envelope on your case file. Two letters are handwritten on it: “R. J.” “Don\'t open it in front of Lisbon,” he whispers. And Lisbon is already standing behind you.',
 speak=['Джейн працює в CBI вже п\'ять років.|Jane pracuje w CBI od pięciu lat.|Jane has worked at the CBI for five years.', 'Чому ти дивишся на мене так?|Dlaczego tak na mnie patrzysz?|Why are you looking at me like that?'],
 fin=('Напиши перший запис у свій робочий журнал (100+ слів): опиши команду — хто що робить щодня, хто що робить просто зараз, і як довго кожен працює в CBI. Окремо — про Джейна: що він помітив у тобі.|Napisz pierwszy wpis w swoim dzienniku pracy (100+ słów): opisz zespół — kto co robi codziennie, kto co robi właśnie teraz i od jak dawna każdy pracuje w CBI. Osobno — o Janie: co w tobie zauważył.|Write the first entry in your work journal (100+ words): describe the team — who does what every day, who is doing what right now and how long each person has worked at the CBI. Separately, write about Jane: what he noticed about you.',
      'Лісабон щодня… Зараз Чо… Ріґсбі працює тут уже… Джейн помітив, що я…|Lisbon codziennie… Teraz Cho… Rigsby pracuje tu od… Jane zauważył, że…|Lisbon always… Right now Cho is… Rigsby has worked here for… Jane noticed that I…'), words=100), A)
